@Component("shipmentItem-handler")
@ProcessingGroup("shipmentItem-processing-group")
public class ShipmentItemEventHandler {
	
	// core constructor
	ShipmentItemEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateShipmentItemEvent
     */
    @EventHandler
    public void handle( CreateShipmentItemEvent event) {
        entityManager.persist(new ShipmentItem(event.getShipmentItemId(), event.getQuantity(), event.getShipment(), event.getOrderLine()));
    }

    /*
     * @param	event UpdateShipmentItemEvent
     */
    @EventHandler
    public ShipmentItem handle( UpdateShipmentItemEvent event) {
    	entityManager.merge(new ShipmentItem(event.getShipmentItemId(), event.getQuantity(), event.getShipment(), event.getOrderLine()));
    }
    
    /*
     * @param	event DeleteShipmentItemEvent
     */
    @EventHandler
    public void on( DeleteShipmentItemEvent event) {
    	ShipmentItem entity = new ShipmentItem();
   
    	// ------------------------------------------
    	// apply the ShipmentItemId
    	// ------------------------------------------
    	entity.setShipmentItemId( event.getShipmentItemId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ShipmentItemRepository shipmentItemEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ShipmentItemEventHandler.class.getName());

}
